import{_ as i,C as t,o as e,c as a,a2 as l,b as A,w as r,a as E,E as C,a3 as n}from"./chunks/framework.BBdhqAg0.js";const B="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",h=JSON.parse('{"title":"역할 및 권한 관리 (Roles & Permissions)","description":"","frontmatter":{},"headers":[],"relativePath":"work-setting/roll-perm.md","filePath":"work-setting/roll-perm.md","lastUpdated":1793112345000}'),c={name:"work-setting/roll-perm.md"};function d(u,o,g,m,p,_){const s=t("Mermaid");return e(),a("div",null,[o[1]||(o[1]=l('<h1 id="역할-및-권한-관리-roles-permissions" tabindex="-1">역할 및 권한 관리 (Roles &amp; Permissions) <a class="header-anchor" href="#역할-및-권한-관리-roles-permissions" aria-label="Permalink to &quot;역할 및 권한 관리 (Roles &amp; Permissions)&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+B+'" alt="역할 및 권한 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/roll-perm.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>역할 및 권한 관리</strong> 페이지는 시스템 관리자가 워크스페이스 및 본사/사업지 관리에서 사용하는 **역할(Role)**을 정의하고, 각 역할별로 수행 가능한 세부 **기능 권한(Permission)**을 3대 비즈니스 도메인 매트릭스를 통해 정밀 제어하는 전사 보안 센터입니다.</p></blockquote><h2 id="_1-개요-및-3대-권한-도메인-아키텍처" tabindex="-1">1. 개요 및 3대 권한 도메인 아키텍처 <a class="header-anchor" href="#_1-개요-및-3대-권한-도메인-아키텍처" aria-label="Permalink to &quot;1. 개요 및 3대 권한 도메인 아키텍처&quot;">​</a></h2><p>IBS 시스템은 비즈니스 영역과 보안 수준에 따라 역할과 권한을 <strong>3대 도메인 범주</strong>로 엄격히 구분하여 관리합니다.</p><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[설정 관리] → [역할 및 권한]**을 선택하여 접속합니다. (관리자 권한 필요)</li></ul>',6)),(e(),A(n,null,{default:r(()=>[C(s,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20%EA%B6%8C%ED%95%9C%EC%B9%B4%ED%85%8C%EA%B3%A0%EB%A6%AC%20%5B%223%EB%8C%80%20%EA%B6%8C%ED%95%9C%20%EB%8F%84%EB%A9%94%EC%9D%B8%20%EC%95%84%ED%82%A4%ED%85%8D%EC%B2%98%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22%F0%9F%8F%A2%201.%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EA%B6%8C%ED%95%9C%20(work_space)%3Cbr%3E%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%C2%B7%ED%9A%8C%EC%9D%98%C2%B7%EC%97%85%EB%AC%B4%C2%B7%EA%B3%B5%EC%A7%80%C2%B7%EB%AC%B8%EC%84%9C%C2%B7%EA%B2%8C%EC%8B%9C%ED%8C%90%C2%B7%EC%BA%98%EB%A6%B0%EB%8D%94%22%5D%0A%20%20%20%20%20%20%20%20B%5B%22%F0%9F%8F%9B%EF%B8%8F%202.%20%EB%B3%B8%EC%82%AC%20%EA%B4%80%EB%A6%AC%20%EA%B6%8C%ED%95%9C%20(ibs_hq_manage)%3Cbr%3E%EC%9D%B8%EC%82%AC%2F%EC%A1%B0%EC%A7%81%C2%B7%EC%9E%90%EA%B8%88%2F%EC%9B%90%EC%9E%A5%20%EA%B4%80%EB%A6%AC%20(%EB%B3%B4%EC%95%88%20%EA%B2%A9%EB%A6%AC%20%EC%A7%80%EC%9B%90)%22%5D%0A%20%20%20%20%20%20%20%20C%5B%22%F0%9F%8F%97%EF%B8%8F%203.%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EA%B4%80%EB%A6%AC%20%EA%B6%8C%ED%95%9C%20(ibs_pr_manage)%3Cbr%3E%EB%B6%84%EC%96%91%EA%B3%84%EC%95%BD%C2%B7%EC%88%98%EB%82%A9%EC%B2%98%EB%A6%AC%C2%B7%EA%B3%A0%EC%A7%80%EB%B0%9C%EC%86%A1%C2%B7%EC%82%AC%EC%97%85%EB%B6%80%EC%A7%80%20%EA%B4%80%EB%A6%AC%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20A%20%26%20B%20%26%20C%20--%3E%20D%5B%22%F0%9F%93%8B%20%EC%97%AD%ED%95%A0(Role)%20%EC%A0%95%EC%9D%98%20%26%20%EC%86%8D%EC%84%B1%20%EC%84%A4%EC%A0%95%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%F0%9F%93%8A%20%EA%B6%8C%ED%95%9C%20%EB%B3%B4%EA%B3%A0%EC%84%9C%20%EC%8B%A4%EC%8B%9C%EA%B0%84%20%EB%A7%A4%ED%8A%B8%EB%A6%AD%EC%8A%A4%20%EC%B2%B4%ED%81%AC%22%5D%0A"})]),fallback:r(()=>[...o[0]||(o[0]=[E(" Loading... ",-1)])]),_:1})),o[2]||(o[2]=l('<h2 id="_2-역할-roles-탭" tabindex="-1">2. 역할 (Roles) 탭 <a class="header-anchor" href="#_2-역할-roles-탭" aria-label="Permalink to &quot;2. 역할 (Roles) 탭&quot;">​</a></h2><p>시스템에서 구성원에게 부여할 역할의 종류를 정의하고 기본 속성 및 보안 격리 여부를 설정합니다.</p><h3 id="📋-역할-생성-및-주요-속성-설정" tabindex="-1">📋 역할 생성 및 주요 속성 설정 <a class="header-anchor" href="#📋-역할-생성-및-주요-속성-설정" aria-label="Permalink to &quot;📋 역할 생성 및 주요 속성 설정&quot;">​</a></h3><p>역할 추가/수정 팝업에서 다음 7대 핵심 속성을 정의합니다:</p><ul><li><strong>이름</strong>: 역할의 직무 명칭 (예: <code>본사 관리자</code>, <code>현장 PM</code>, <code>분양 담당자</code>, <code>협력업체</code>, <code>단순 열람자</code> 등)</li><li><strong>권한 구분 (카테고리)</strong>: <ul><li><strong><code>워크스페이스</code></strong>: 일반 협업 모듈(업무, 회의, 문서 등) 전용 역할</li><li><strong><code>본사 관리</code></strong>: 본사 경영지원, 재경, 인사 직무 전용 역할</li><li><strong><code>프로젝트 관리</code></strong>: 부동산 개발 시행 사업지(분양, 계약, 수납 등) 직무 전용 역할</li></ul></li><li><strong>보안 격리 역할 여부</strong>: <ul><li>최고 관리자(슈퍼유저)만 다룰 수 있는 민감한 역할로 지정합니다. 일반 관리자 화면에서도 해당 역할의 정보와 권한이 완벽히 격리되어 임의 조작을 방어합니다.</li></ul></li><li><strong>부동산 개발 프로젝트 기본 적용</strong>: <ul><li>체크 시 향후 새로 개설되는 모든 부동산 개발 프로젝트에 기본 멤버 역할로 자동 포함됩니다.</li></ul></li><li><strong>업무 할당 가능 여부</strong>: <ul><li>이 역할을 가진 사용자를 업무(Issue)의 &#39;담당자&#39;로 지정할 수 있는지 통제합니다. 외부 협력사나 단순 열람 목적의 역할인 경우 체크를 해제하여 담당자로 오배정되는 것을 방지합니다.</li></ul></li><li><strong>업무 보기 범위</strong>: <ul><li><code>모든 업무</code> / <code>비공개 업무 제외</code> / <code>직접 생성 또는 담당한 업무만</code> / <code>없음</code> 중 선택</li></ul></li><li><strong>사용자 목록 보기 범위</strong>: <ul><li><code>모든 활성 사용자</code> / <code>자신이 속한 프로젝트 구성원만</code> / <code>없음</code> 중 선택</li></ul></li></ul><h2 id="_3-권한-보고서-permission-report-탭" tabindex="-1">3. 권한 보고서 (Permission Report) 탭 <a class="header-anchor" href="#_3-권한-보고서-permission-report-탭" aria-label="Permalink to &quot;3. 권한 보고서 (Permission Report) 탭&quot;">​</a></h2><p>정의된 각 역할에 대해 기능별 세부 권한을 부여하는 <strong>3단 아코디언 매트릭스</strong> 화면입니다.</p><h3 id="📊-3대-도메인-아코디언-구조" tabindex="-1">📊 3대 도메인 아코디언 구조 <a class="header-anchor" href="#📊-3대-도메인-아코디언-구조" aria-label="Permalink to &quot;📊 3대 도메인 아코디언 구조&quot;">​</a></h3><ol><li><strong>워크스페이스 권한군</strong>: <ul><li>프로젝트(생성/수정/삭제/모듈제어), 회의록(작성/확정), 업무(생성/수정/댓글), 공지사항, 문서(보안등급별 열람/등록), 게시판, 캘린더</li></ul></li><li><strong>본사 관리 권한군</strong>: <ul><li>인사/조직 관리(부서, 직급, 근태, 평가), 본사 자금 및 회계원장</li></ul></li><li><strong>프로젝트 관리 권한군</strong>: <ul><li>계약 관리(동호수 매핑, 계약자, 양도양수), 수납 및 청구(대금 수납, 분양가, 연체이자), 고객 고지, 사업부지(토지 매입 관리)</li></ul></li></ol><h3 id="⚡-실시간-자동-저장-auto-save" tabindex="-1">⚡ 실시간 자동 저장 (Auto-save) <a class="header-anchor" href="#⚡-실시간-자동-저장-auto-save" aria-label="Permalink to &quot;⚡ 실시간 자동 저장 (Auto-save)&quot;">​</a></h3><ul><li>각 역할과 권한이 교차하는 지점의 <strong>체크박스를 클릭하는 즉시 시스템에 실시간 자동 반영</strong>됩니다.</li><li>별도의 &#39;저장&#39; 버튼을 누를 필요가 없으며, 변경 사항이 즉각 적용됩니다.</li><li>권한 수정은 전사 총괄 관리자 이상의 최고 권한을 가진 계정만 수행할 수 있습니다.</li></ul><h2 id="_4-권한-설계-모범-사례-best-practices" tabindex="-1">4. 권한 설계 모범 사례 (Best Practices) <a class="header-anchor" href="#_4-권한-설계-모범-사례-best-practices" aria-label="Permalink to &quot;4. 권한 설계 모범 사례 (Best Practices)&quot;">​</a></h2><ul><li><strong>최소 권한의 원칙 (Security First)</strong>: <ul><li>외부 협력업체나 지원 부서에는 &#39;비공개 업무 제외&#39; 및 &#39;직접 생성/담당한 업무만&#39; 볼 수 있도록 업무 보기 범위를 설정하여 회사의 주요 기밀 정보를 안전하게 보호하십시오.</li></ul></li><li><strong>보안 격리 기능 적극 활용</strong>: <ul><li>인사 평가나 임원 급여, 감사 부서와 관련된 역할은 반드시 <strong>&#39;보안 격리 역할&#39;</strong> 속성을 켜두어, 일반 워크스페이스 관리자가 임의로 권한을 조정하지 못하도록 원천 차단하십시오.</li></ul></li><li><strong>기본 시스템 역할 이해</strong>: <ul><li>시스템에 내장된 기본 역할(익명 사용자, 일반 비회원 등)은 워크스페이스 멤버 배정에서 제외되도록 안전하게 보호되므로 임의로 수정하지 않는 것을 권장합니다.</li></ul></li></ul>',13))])}const b=i(c,[["render",d]]);export{h as __pageData,b as default};
